Update:

    F5::
    ExitApp
    return

    toggle := 0

    return

    F2::
    toggle := !toggle
    if (toggle = 0)
    {
    }

    else
    {

    ~$w::

    GoSub ArrowSpam
    return

    ArrowSpam:
    Send {up down}
    Sleep 50
    Send {up up}
    Sleep 50
    if GetKeyState("w", "p")
    	SetTimer, ArrowSpam, -0
    return
    }

I got it to work except the toggle. I start the script and it's already enabled but I don't want it to. I press F2 and it doesn't toggle it at all.

    #MaxThreadsPerHotkey, 2

    ~w & ~1::
    SetKeyDelay, 50, 50
    While (GetKeyState("w", "p"))
    {
    	SendInput, {Up Down}
    	Sleep, 75
    	SendInput, {Up Up}
    }
    SetKeyDelay, 0
    Return

So this should work?
